import{_ as r,a0 as o,w as p,s as d,ao as l,I as n,x as e,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"基礎：在 Linux 終端中刪除文件和文件夾 | LCTT x X-CMD","titleTemplate":false,"description":"基礎：在 Linux 終端中刪除文件和文件夾 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基礎：在 Linux 終端中刪除文件和文件夾 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基礎：在 Linux 終端中刪除文件和文件夾 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210807 Remove files and folders in the Linux terminal","title":"基礎：在 Linux 終端中刪除文件和文件夾","tag":"202108","desc":""},"relativePath":"202108/20210807 Remove files and folders in the Linux terminal.md","filePath":"[post].md"}'),h={name:"202108/20210807 Remove files and folders in the Linux terminal.md"};function u(m,s,g,f,k,b){const a=o("Link");return p(),d("div",null,[s[20]||(s[20]=l(`<h1 id="基礎-在-linux-終端中刪除文件和文件夾" tabindex="-1">基礎：在 Linux 終端中刪除文件和文件夾 <a class="header-anchor" href="#基礎-在-linux-終端中刪除文件和文件夾" aria-label="Permalink to “基礎：在 Linux 終端中刪除文件和文件夾”">​</a></h1><blockquote><p>本教程講述瞭如何在 Linux 終端中安全地刪除文件和文件夾。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/16/110943z9boolgobdlyoiyo.jpg" alt=""></p><p>要想使用圖形化界面刪除計算機上的文件，你可能會直接將文件或文件夾拖拽到 “垃圾箱” 或 “回收站”。或者你也可以選擇要刪除的文件或文件夾，右鍵單擊並選擇 <strong>刪除</strong>。</p><p>而在終端中刪除文件或文件夾時並沒有垃圾箱一説（至少默認情況下沒有）。在圖形化桌面上，<code>Trash</code>（即垃圾箱文件夾）是一個受保護的目錄，保護機制可以防止用户不小心將該目錄刪除，或將其從默認位置移動從而導致找不到它。Trash 本質不過是一個被高度管理的文件夾，因此你可以創建自己的 Trash 文件夾以在終端中使用。</p><h3 id="為終端設置一個垃圾箱" tabindex="-1">為終端設置一個垃圾箱 <a class="header-anchor" href="#為終端設置一個垃圾箱" aria-label="Permalink to “為終端設置一個垃圾箱”">​</a></h3><p>在家目錄中創建一個名為 <code>Trash</code> 的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/Trash</span></span></code></pre></div><h3 id="刪除文件" tabindex="-1">刪除文件 <a class="header-anchor" href="#刪除文件" aria-label="Permalink to “刪除文件”">​</a></h3><p>要刪除文件或文件夾時，使用 <code>mv</code> 命令將文件或文件夾移至 <code>Trash</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv example.txt ~/Trash</span></span></code></pre></div><h3 id="永久刪除文件或文件夾" tabindex="-1">永久刪除文件或文件夾 <a class="header-anchor" href="#永久刪除文件或文件夾" aria-label="Permalink to “永久刪除文件或文件夾”">​</a></h3><p>當你準備從系統中永久刪除某個文件或文件夾時，可以使用 <code>rm</code> 命令清除垃圾箱文件夾中的所有數據。通過將 <code>rm</code> 命令指向星號（<code>*</code>），可以刪除 <code>Trash</code> 文件夾內的所有文件和文件夾，而不會刪除 <code>Trash</code> 文件夾本身。因為用户可以方便且自由地創建目錄，所以即使不小心刪除了 <code>Trash</code> 文件夾，你也可以再次新建一個。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rm --recursive ~/Trash/*</span></span></code></pre></div><h3 id="刪除空目錄" tabindex="-1">刪除空目錄 <a class="header-anchor" href="#刪除空目錄" aria-label="Permalink to “刪除空目錄”">​</a></h3><p>刪除空目錄有一個專門的命令 <code>rmdir</code>，它只能用來刪除空目錄，從而保護你免受遞歸刪除錯誤的影響。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir full</span></span>
<span class="line"><span>$ touch full/file.txt</span></span>
<span class="line"><span>$ rmdir full</span></span>
<span class="line"><span>rmdir: failed to remove &#39;full/&#39;: Directory not empty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ mkdir empty</span></span>
<span class="line"><span>$ rmdir empty</span></span></code></pre></div><h3 id="更好的刪除方式" tabindex="-1">更好的刪除方式 <a class="header-anchor" href="#更好的刪除方式" aria-label="Permalink to “更好的刪除方式”">​</a></h3>`,18)),n("p",null,[s[1]||(s[1]=e("此外還有一些並沒有默認安裝在終端上的 ",-1)),i(a,{href:"https://www.redhat.com/sysadmin/recover-file-deletion-linux"},{default:t(()=>[...s[0]||(s[0]=[e("刪除文件命令",-1)])]),_:1}),s[2]||(s[2]=e("，你可以從軟件庫安裝它們。這些命令管理和使用的 ",-1)),s[3]||(s[3]=n("code",null,"Trash",-1)),s[4]||(s[4]=e(" 文件夾與你在桌面模式使用的是同一個（而非你自己單獨創建的），從而使刪除文件變得更加方便。",-1))]),s[21]||(s[21]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ trash ~/example.txt</span></span>
<span class="line"><span>$ trash --list</span></span>
<span class="line"><span>example.txt</span></span>
<span class="line"><span>$ trash --empty</span></span></code></pre></div><hr>`,2)),n("p",null,[s[6]||(s[6]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/21/8/remove-files-linux-terminal"},{default:t(()=>[...s[5]||(s[5]=[e("https://opensource.com/article/21/8/remove-files-linux-terminal",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[7]||(s[7]=[e("Seth Kenlon",-1)])]),_:1}),s[12]||(s[12]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[e("lujun9972",-1)])]),_:1}),s[13]||(s[13]=e(" 譯者：",-1)),i(a,{href:"https://github.com/unigeorge"},{default:t(()=>[...s[9]||(s[9]=[e("unigeorge",-1)])]),_:1}),s[14]||(s[14]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[e("LCTT",-1)])]),_:1}),s[18]||(s[18]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[e("Linux中國",-1)])]),_:1}),s[19]||(s[19]=e(" 榮譽推出",-1))])])}const C=r(h,[["render",u]]);export{T as __pageData,C as default};
